<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,apiResult,errorText} from '@/lib/api'
import {can} from '@/lib/auth'
import {pretty,dateTime} from '@/lib/format'
import ProtocolDraftEditor from '@/features/ai/ProtocolDraftEditor.vue'
import {clone,enc,jobLabels,normalizeContent,safeReturnTo,taskLabels,base64ToHex,validationMessage,draftStructureError,type AIRecord} from '@/features/ai/helpers'
const route=useRoute(),router=useRouter(),job=ref<AIRecord>(),draft=ref<AIRecord>(),content=ref<AIRecord>(normalizeContent({})),etag=ref(''),error=ref(''),busy=ref(false),loading=ref(false),dirty=ref(false),mobileTab=ref('draft'),docId=ref(''),evidence=ref<AIRecord[]>([]),evidenceId=ref(''),sourcePath=ref('parserSpec'),sourceKind=ref('DOCUMENT'),sourceNote=ref(''),sourceQuote=ref(''),validation=ref<AIRecord>(),published=ref<AIRecord>(),version=ref('1.0.0'),advanced=ref(false),advancedText=ref(''),testDrafts=ref<AIRecord[]>([]),editor=ref<InstanceType<typeof ProtocolDraftEditor>>()
let timer:ReturnType<typeof setTimeout>|undefined,generation=0
const structureError=computed(()=>draftStructureError(content.value)),parserFields=computed(()=>Array.isArray(content.value.parserSpec?.fields)?content.value.parserSpec.fields.filter((f:any)=>f&&typeof f==='object'):[])
const mappingOnly=computed(()=>!content.value.parserSpec&&!!content.value.mappingSpec)
const jobId=computed(()=>String(route.params.jobId)),canEdit=computed(()=>!!draft.value&&draft.value.state!=='PUBLISHED'&&can('profile:write',draft.value.scopeId)),canPublish=computed(()=>!!draft.value&&can('profile:publish',draft.value.scopeId)),selectedEvidence=computed(()=>evidence.value.find(e=>e.evidenceId===evidenceId.value)),pendingIssues=computed(()=>(content.value.issues||[]).filter((i:AIRecord)=>!i.resolved)),step=computed(()=>published.value||draft.value?.state==='PUBLISHED'?5:validation.value?.passed&&!dirty.value?4:draft.value?2:job.value?.state==='GENERATING'?1:0),returnTo=computed(()=>safeReturnTo(job.value?.sourceContext?.returnTo)),documents=computed(()=>job.value?.documents||[]),running=computed(()=>['QUEUED','GENERATING'].includes(job.value?.state))
function markDirty(){dirty.value=true;validation.value=undefined}
function setDraft(value:AIRecord,header:string){draft.value=value;etag.value=header||'"'+value.revision+'"';content.value=normalizeContent(value.content);testDrafts.value=(content.value.tests||[]).map((t:AIRecord)=>({...clone(t),payloadHex:t.payloadHex||base64ToHex(t.payloadBase64||''),inputText:pretty(t.input||{}),expectedText:pretty(t.expected||[])}));validation.value=value.validation?.validationId?value.validation:undefined;dirty.value=false}
async function loadDraft(){const id=job.value?.draftId,current=generation;if(!id)return;const result=await apiResult('/api/v1/protocol-drafts/'+enc(id));if(current!==generation||job.value?.draftId!==id)return;setDraft(result.data,result.etag);if(result.data.publishedModelId){const model=await api('/api/v1/device-models/'+enc(result.data.publishedModelId));if(current===generation)published.value=model}}
async function discard(){try{await ElMessageBox.confirm('放弃尚未保存的修改，重新载入服务器草稿。','重新载入草稿',{confirmButtonText:'放弃修改并载入',cancelButtonText:'继续编辑'});await loadDraft();error.value=''}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}}

async function refresh(reload=false){const current=generation;try{const response=await api('/api/v1/ai/import-jobs/'+enc(jobId.value));if(current!==generation)return;job.value=response;if(response.draftId&&(!draft.value||reload&&!dirty.value))await loadDraft();if(!docId.value&&response.documents?.length)docId.value=response.documents[0].documentId;if(['QUEUED','GENERATING'].includes(response.state)){clearTimeout(timer);timer=setTimeout(()=>void refresh(),2000)}}catch(e){if(current===generation)error.value=errorText(e)}}
async function load(){clearTimeout(timer);generation++;loading.value=true;error.value='';job.value=undefined;draft.value=undefined;published.value=undefined;validation.value=undefined;docId.value='';evidence.value=[];dirty.value=false;try{await refresh()}finally{loading.value=false}}
function buildContent(){const result=clone(content.value);result.tests=testDrafts.value.map(t=>{const test:AIRecord={name:t.name,source:t.source||'USER'};if(mappingOnly.value){try{test.input=JSON.parse(t.inputText||'{}')}catch{throw new Error('映射样例输入必须为有效 JSON 对象')}if(!test.input||typeof test.input!=='object'||Array.isArray(test.input))throw new Error('映射样例输入必须为对象')}else if(t.payloadBase64&&!t.payloadHex)test.payloadBase64=t.payloadBase64;else test.payloadHex=t.payloadHex||'';if(t.expectError)test.expectError=true;else{try{test.expected=JSON.parse(t.expectedText||'[]')}catch{throw new Error('测试样例 '+(t.name||'未命名')+' 的预期输出不是有效 JSON')}if(!Array.isArray(test.expected))throw new Error('预期输出需为 JSON 数组，例如 [{"temperature":25}]')}return test});return result}
async function save(){if(!draft.value||!canEdit.value)return false;busy.value=true;error.value='';try{const result=await apiResult('/api/v1/protocol-drafts/'+enc(draft.value.draftId),'PATCH',{content:buildContent()},{etag:etag.value});setDraft(result.data,result.etag);ElMessage.success('草稿已保存到服务器');return true}catch(e){error.value=errorText(e);return false}finally{busy.value=false}}
async function validate(){if(!draft.value)return;if(dirty.value&&!(await save()))return;busy.value=true;error.value='';try{validation.value=await api('/api/v1/protocol-drafts/'+enc(draft.value.draftId)+'/validations','POST',{draftRevision:draft.value.revision});mobileTab.value='validation';await refresh();ElMessage[validation.value?.passed?'success':'warning'](validation.value?.passed?'验证通过，尚未发布':'请处理验证问题后再次运行')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function publish(){if(!draft.value||!validation.value?.passed||dirty.value)return;busy.value=true;error.value='';try{await ElMessageBox.confirm('将发布 '+content.value.modelName+' 的不可变版本 '+version.value+'。此操作不会连接设备或激活规则。','确认发布模板',{confirmButtonText:'发布模板',cancelButtonText:'返回审阅'});published.value=await api('/api/v1/protocol-drafts/'+enc(draft.value.draftId)+'/publications','POST',{draftRevision:draft.value.revision,validationId:validation.value.validationId,version:version.value});await loadDraft();ElMessage.success('模板已发布，可到型号库选择实际设备应用')}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
async function jobAction(action:string){busy.value=true;error.value='';try{job.value=await api('/api/v1/ai/import-jobs/'+enc(jobId.value)+'/'+action,'POST',{});await refresh()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function addTest(){testDrafts.value.push({name:'样例 '+(testDrafts.value.length+1),payloadHex:'',inputText:'{}',source:'USER',expectedText:'[\n  {}\n]',expectError:false});markDirty()}
function inspectSource(path:string){sourcePath.value=path;const source=(content.value.sources||[]).find((s:AIRecord)=>s.path===path)||(content.value.sources||[]).find((s:AIRecord)=>path.startsWith(s.path+'.'));if(source){sourceKind.value=source.state||'DOCUMENT';sourceNote.value=source.note||'';sourceQuote.value=source.quote||'';evidenceId.value=source.evidenceId||''}mobileTab.value='evidence';document.getElementById('source-editor')?.scrollIntoView({block:'nearest',behavior:'smooth'})}
function addSource(){error.value='';try{if(!sourcePath.value.trim())throw new Error('请选择配置范围');const source:AIRecord={path:sourcePath.value,state:sourceKind.value};if(sourceKind.value==='USER'){if(sourceNote.value.trim().length<5)throw new Error('请填写至少 5 个字的人工依据');source.note=sourceNote.value.trim()}else{if(!selectedEvidence.value)throw new Error('请先选取原文证据');const quote=sourceQuote.value.trim()||selectedEvidence.value.text;if(!selectedEvidence.value.text.includes(quote))throw new Error('引用必须是所选原文的真实片段');Object.assign(source,{evidenceId:evidenceId.value,quote})}content.value.sources=(content.value.sources||[]).filter((s:AIRecord)=>s.path!==source.path);content.value.sources.push(source);markDirty();ElMessage.success('配置依据已记录，保存草稿后生效')}catch(e){error.value=errorText(e)}}
function openAdvanced(){try{advancedText.value=pretty(buildContent());advanced.value=true}catch(e){error.value=errorText(e)}}
function applyAdvanced(){try{const parsed=JSON.parse(advancedText.value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('草稿必须为对象');content.value=normalizeContent(parsed);testDrafts.value=(content.value.tests||[]).map((t:AIRecord)=>({...t,payloadHex:t.payloadHex||base64ToHex(t.payloadBase64||''),inputText:pretty(t.input||{}),expectedText:pretty(t.expected||[])}));markDirty();advanced.value=false}catch(e){error.value=errorText(e)}}
async function leave(){if(dirty.value){try{await ElMessageBox.confirm('当前修改尚未保存到服务器。离开会丢弃这些修改。','离开草稿',{confirmButtonText:'放弃修改并离开',cancelButtonText:'继续编辑',type:'warning'})}catch{return false}}return true}
onBeforeRouteLeave(leave)
watch(docId,async id=>{evidence.value=[];evidenceId.value='';if(!id)return;try{const result=await api('/api/v1/source-documents/'+enc(id)+'/evidence');if(docId.value===id)evidence.value=result.items||[]}catch(e){error.value=errorText(e)}})
watch(evidenceId,()=>{sourceQuote.value=selectedEvidence.value?.text?.slice(0,2000)||''})
watch(()=>route.params.jobId,load,{immediate:true})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload))
onBeforeUnmount(()=>{clearTimeout(timer);generation++;window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><div v-loading="loading" class="workbench">
<div class="page-heading"><div><el-button link @click="router.push(returnTo)">← 返回来源页面</el-button><h1>导入审阅工作台</h1><p>{{taskLabels[job?.taskKind]||'设备资料'}} · {{jobLabels[job?.state]||'加载中'}}<span v-if="draft"> · 草稿修订 {{draft.revision}} · {{dirty?'有未保存修改':'已保存到服务器'}}</span></p></div><div class="toolbar"><el-button :disabled="busy" @click="refresh(true)">刷新状态</el-button><el-button v-if="dirty" :disabled="busy" @click="discard">放弃未保存修改</el-button><el-button v-if="running" :disabled="busy" @click="jobAction('cancellation')">取消后续处理</el-button><el-button v-if="job?.state==='FAILED'" :disabled="busy" @click="jobAction('retries')">重试失败任务</el-button></div></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="job?.errorCode" :title="job.errorCode+' · '+(job.message||'')" type="warning" :closable="false"/>
<el-steps :active="step" finish-status="success" simple class="import-steps"><el-step v-for="label in ['上传资料','识别范围','审阅草稿','样例验证','发布版本','现场应用']" :key="label" :title="label"/></el-steps>
<section v-if="running&&!draft" class="panel"><h2>资料正在后台处理</h2><p>{{job?.phase||'等待任务执行'}}。可以离开页面，稍后从型号库的“导入任务与草稿”继续。</p><p class="muted">显示真实阶段，不使用估算百分比。生成结果仍需审阅与测试后才能发布。</p></section>
<el-radio-group v-model="mobileTab" class="mobile-pane-tabs"><el-radio-button value="evidence">原文与依据</el-radio-button><el-radio-button value="draft">配置草稿</el-radio-button><el-radio-button value="validation">问题与验证</el-radio-button></el-radio-group>
<div class="review-grid" v-if="job">
<aside class="panel evidence-pane" :class="{'mobile-active':mobileTab==='evidence'}"><h2 class="section-title">原文证据</h2><el-select v-model="docId" placeholder="选择资料文件" style="width:100%" :disabled="!documents.length"><el-option v-for="d in documents" :key="d.documentId" :label="d.name" :value="d.documentId"/></el-select><template v-for="d in documents.filter((d:AIRecord)=>d.documentId===docId)" :key="d.documentId"><p class="muted">{{d.extractionState}} · {{d.evidenceCount}} 条提取记录</p><p v-for="(warning,i) in d.warnings" :key="i" class="muted">{{warning}}</p><a :href="'/api/v1/source-documents/'+enc(d.documentId)+'/content'" download>下载原始资料</a></template><el-empty v-if="!documents.length" description="人工草稿，可记录人工依据"/>
<div class="evidence-list"><button v-for="item in evidence" :key="item.evidenceId" class="evidence-card" :class="{selected:evidenceId===item.evidenceId}" @click="evidenceId=item.evidenceId"><strong>{{item.location||('第 '+item.page+' 页')}}</strong><span>{{item.text}}</span></button><p v-if="docId&&!evidence.length" class="muted">暂无可提取的文字证据。扫描页可能需要支持图像的服务，或补充文字协议。</p></div>
<section id="source-editor" v-if="draft"><h3>配置依据</h3><el-form label-position="top" :disabled="!canEdit||busy"><el-form-item label="关联配置范围"><el-select v-model="sourcePath" filterable allow-create style="width:100%"><el-option label="整个解析方案" value="parserSpec"/><el-option label="整个连接方案" value="connectionSpec"/><el-option label="整个字段映射" value="mappingSpec"/><el-option v-for="(f,i) in parserFields" :key="i" :label="'字段 '+(f.name||Number(i)+1)" :value="'parserSpec.fields.'+i"/></el-select></el-form-item><el-form-item label="来源"><el-radio-group v-model="sourceKind"><el-radio value="DOCUMENT">资料原文</el-radio><el-radio value="USER">人工依据</el-radio></el-radio-group></el-form-item><el-form-item v-if="sourceKind==='DOCUMENT'" label="原文引用"><el-input v-model="sourceQuote" type="textarea" :rows="4" placeholder="点击上方原文段落，可裁剪引用内容"/><span class="muted">必须是已上传证据中的原文片段。</span></el-form-item><el-form-item v-else label="人工确认依据"><el-input v-model="sourceNote" type="textarea" :rows="3" placeholder="至少 5 字，例如依据厂商补充邮件核对"/></el-form-item><el-button :disabled="!canEdit" @click="addSource">记录依据</el-button></el-form><p class="muted">已记录 {{content.sources?.length||0}} 项依据。整段协议的来源可覆盖已核对的全部字段。</p></section></aside>
<section class="panel draft-pane" :class="{'mobile-active':mobileTab==='draft'}"><div class="section-title draft-title"><h2>配置草稿</h2><el-button v-if="draft" link @click="openAdvanced">高级结构</el-button></div><el-alert v-if="structureError" :title="structureError" type="warning" :closable="false"/><ProtocolDraftEditor v-if="draft&&!structureError" ref="editor" :content="content" :disabled="!canEdit||busy" @change="markDirty" @evidence="inspectSource"/><el-empty v-else description="草稿尚未生成"/><template v-if="draft"><h3>测试样例</h3><p class="muted">至少提供 1 个人工核对的有效样例和 1 个应拒绝的异常样例。预期结果包括单位字段；同时配置解析与映射时，输入原始报文，预期填写映射后的最终输出。模型样例须核对后明确标为人工已确认，不能单独证明协议正确。</p><div v-for="(test,i) in testDrafts" :key="i" class="test-card"><el-form label-position="top" :disabled="!canEdit||busy" @input="markDirty"><div class="test-heading"><el-input v-model="test.name" placeholder="样例名称"/><el-button link type="danger" @click="testDrafts.splice(i,1);markDirty()">移除</el-button></div><el-form-item v-if="mappingOnly" label="映射输入 JSON 对象"><el-input v-model="test.inputText" type="textarea" :rows="4" placeholder='{"temperature":25}'/></el-form-item><el-form-item v-else label="报文 HEX"><el-input v-model="test.payloadHex" type="textarea" :rows="2" placeholder="例如 2E 09 88 13"/></el-form-item><el-form-item label="样例来源"><el-select v-model="test.source" @change="markDirty"><el-option label="文档原始样例（已核对）" value="DOCUMENT"/><el-option label="人工已核对" value="USER"/><el-option label="模型生成辅助样例" value="MODEL"/></el-select></el-form-item><el-checkbox v-model="test.expectError" @change="markDirty">异常样例，应被解析或映射拒绝</el-checkbox><el-form-item v-if="!test.expectError" label="预期字段数组"><el-input v-model="test.expectedText" type="textarea" :rows="4" placeholder='[{"temperature":23.5}]'/></el-form-item></el-form></div><el-button v-if="canEdit" @click="addTest">添加测试样例</el-button></template></section>
<aside class="panel validation-pane" :class="{'mobile-active':mobileTab==='validation'}"><h2 class="section-title">问题与验证</h2><template v-if="draft"><div class="review-summary"><strong>{{pendingIssues.length}}</strong><span>项尚待处理</span></div><div v-for="(issue,i) in content.issues||[]" :key="i" class="issue-card"><strong>{{issue.code}}</strong><p>{{issue.message}}</p><span class="mono muted">{{issue.path}}</span><el-input v-model="issue.resolution" type="textarea" :rows="2" :disabled="!canEdit" placeholder="说明如何核实或解决" @input="markDirty"/><el-checkbox v-model="issue.resolved" :disabled="!canEdit" @change="markDirty">已核实处理</el-checkbox></div>
<template v-if="validation"><el-alert :title="validation.passed?'当前草稿验证通过':'当前草稿验证未通过'" :type="validation.passed?'success':'warning'" :closable="false"/><p class="muted">验证修订 {{validation.draftRevision}} · {{dateTime(validation.verifiedAt)}}</p><div v-for="(item,i) in validation.errors||[]" :key="i" class="issue-card"><strong>{{item.code}}</strong><p>{{validationMessage(item)}}</p><span class="mono muted">{{item.path}}</span></div><el-collapse><el-collapse-item v-for="(test,i) in validation.testResults||[]" :key="i" :title="(test.passed?'通过 · ':'未通过 · ')+test.name"><pre>{{pretty({outputs:test.outputs,errors:test.errors})}}</pre></el-collapse-item></el-collapse></template>
<p v-else class="muted">保存后运行确定性验证。字段来源、协议边界、样例和未决问题都必须通过检查。</p>
<template v-if="canPublish&&draft.state!=='PUBLISHED'"><el-form label-position="top"><el-form-item label="发布版本"><el-input v-model="version" placeholder="1.0.0"/></el-form-item></el-form></template><p v-if="!canPublish" class="muted">当前角色可以准备草稿；发布需由有权限的管理员完成。</p>
<div v-if="published||draft.state==='PUBLISHED'" class="published"><h3>模板已发布</h3><p>下一步选择实际设备和网关。发布没有产生物理操作或激活现网规则。</p><el-button type="primary" @click="router.push({path:'/device-models',query:{modelId:published?.modelId||draft.publishedModelId}})">到型号库应用</el-button><el-button v-if="published&&job?.sourceContext?.pageId==='P14'" @click="router.push({path:returnTo.split('?')[0],query:{modelId:published.modelId}})">带回客户转发目标</el-button></div></template></aside>
</div>
<footer v-if="draft" class="workbench-actions"><span class="muted">{{dirty?'修改尚未保存':'草稿已保存'}} · {{draft.state==='PUBLISHED'?'已发布版本不可编辑':'生成与保存不会执行设备操作'}}</span><div><el-button :disabled="!canEdit||busy||!dirty" @click="save">保存草稿</el-button><el-button :disabled="!canEdit||busy" @click="validate">运行验证</el-button><el-button v-if="canPublish&&draft.state!=='PUBLISHED'" type="primary" :disabled="busy||dirty||!validation?.passed" @click="publish">确认发布</el-button></div></footer>
<el-dialog v-model="advanced" title="高级结构化草稿" width="min(900px, 95vw)" :close-on-click-modal="false"><p class="muted">只编辑受限协议结构，不支持运行脚本。修改后仍须重新验证。</p><el-input v-model="advancedText" type="textarea" :rows="23" :readonly="!canEdit"/><template #footer><el-button @click="advanced=false">关闭</el-button><el-button v-if="canEdit" type="primary" @click="applyAdvanced">采用结构修改</el-button></template></el-dialog>
</div></template>
<style scoped>.import-steps{margin-bottom:22px}.review-grid{display:grid;grid-template-columns:minmax(220px,.85fr) minmax(340px,1.5fr) minmax(220px,.85fr);gap:16px;align-items:start}.review-grid>.panel{padding:17px;min-width:0}.draft-title{display:flex;justify-content:space-between;align-items:center}.draft-title h2{font-size:16px;margin:0}.evidence-list{max-height:490px;overflow:auto;margin:18px 0}.evidence-card{display:block;text-align:left;width:100%;padding:12px;margin:0 0 9px;background:#f8fafb;border:1px solid #dce6eb;border-radius:6px;color:#314c5a;cursor:pointer;font-size:12px;line-height:1.7}.evidence-card strong{display:block;margin-bottom:7px}.evidence-card span{white-space:pre-wrap;overflow-wrap:anywhere}.evidence-card.selected{background:#eaf5f6;border-color:#418f9a}.review-summary{display:flex;gap:10px;align-items:baseline;margin-bottom:20px;color:#667e8a}.review-summary strong{font-size:32px;color:#264957}.issue-card{background:#f9fafb;border:1px solid #dfe6ea;border-radius:6px;padding:13px;margin-bottom:12px;font-size:12px;overflow-wrap:anywhere}.issue-card p{margin:7px 0}.issue-card .el-input{margin-top:10px}.issue-card .el-checkbox{white-space:normal}.test-card{border:1px solid #dfe7eb;border-radius:7px;padding:14px;margin:14px 0}.test-heading{display:flex;gap:10px;align-items:center;margin-bottom:15px}.test-card .el-select{width:100%}.published{padding-top:20px;border-top:1px solid #dfe7eb}.published .el-button{margin:6px 0}.workbench-actions{position:sticky;bottom:0;padding:16px 18px;background:#fff;border:1px solid #dce5e9;border-radius:8px;display:flex;justify-content:space-between;align-items:center;gap:12px;z-index:5;box-shadow:0 -4px 18px #142e3910}.workbench-actions>div{display:flex;gap:8px;flex-wrap:wrap}.workbench-actions .el-button{margin:0}.mobile-pane-tabs{display:none;margin-bottom:16px}.validation-pane pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}.workbench .el-form-item :deep(.el-form-item__label){white-space:norma